	.byte 0xff	; 9FA078
	.asciz "Technics KN5000 Table    DATA FILE 2/2"
	.byte 0xff	; 9FA0A0
	.asciz "Technics KN5000 Table    DATA FILE PCK"
	.byte 0xff	; 9FA0C8
	.asciz "Technics KN5000 CMPCUSTOMDATA FILE    "
	.byte 0x00	; 9FA0F0
	.asciz "Technics KN5000 HD-AEPRG DATA FILE    "
	.byte 0xf0	; 9FA118
	; Data between strings and SLIDE marker (0x9FA140 - 0x9FA14F)
	.byte 0x00, 0x00, 0x9b, 0x00, 0x20, 0x00, 0x9b, 0x00
	.byte 0x43, 0x00, 0x5b, 0x00, 0x76, 0x00, 0x8f, 0x00

