	VGA_SEQUENCER 0xa, 0x0
	VGA_SEQUENCER 0xb, 0x72
	VGA_SEQUENCER 0xc, 0x9

	VGA_SEQUENCER 0x9, 0xf
	VGA_SEQUENCER 0xa, 0x11

	VGA_SEQUENCER 0x9, 0xe
	VGA_SEQUENCER 0xa, 0x0
	VGA_SEQUENCER 0xb, 0x13
