; =============================================================================
; VGA_Setup - Main VGA Initialization
; =============================================================================
; Complete VGA hardware initialization:
;   1. Enable VGA and set misc output
;   2. Configure sequencer (clocking, map mask, memory mode)
;   3. Configure graphics controller
;   4. Configure CRTC timing
;   5. Set attribute controller (EGA palette)
;   6. Set DAC palette (9 basic colors)
;   7. Call extended init
;   8. Prepare registers for video buffer initialization
;
; After this code, the caller must:
;   - CALL a memory fill routine to clear the offscreen buffer
;   - CALL a memory copy routine to blit to video RAM
;   - Set VGA_SEQUENCER 01h, 001h to turn the screen on
; =============================================================================
VGA_Setup:
	VGA_WRITE VGA_ENABLE, 0x1	; Global enable
	VGA_WRITE VGA_MISC_OUTPUT, 0xe3	; 25 MHz dot clock, 60 Hz scanning

	VGA_SEQUENCER 0x0, 0x0	; Reset
	VGA_SEQUENCER 0x1, 0x21	; Clocking Mode (screen off)
	VGA_SEQUENCER 0x0, 0x3	; Reset
	VGA_SEQUENCER 0x2, 0xf	; Map Mask (all 4 planes)
	VGA_SEQUENCER 0x3, 0x0	; Character Map Select
	VGA_SEQUENCER 0x4, 0x6	; Memory Mode

	VGA_GFX_CONTROLLER GC_ENABLE_SET_RESET, 0x0
	VGA_GFX_CONTROLLER GC_DATA_ROTATE, 0x0
	VGA_GFX_CONTROLLER GC_READ_MAP_SELECT, 0x0
	VGA_GFX_CONTROLLER GC_GRAPHICS_MODE, 0x0
	VGA_GFX_CONTROLLER GC_MISC_GRAPHICS, 0x1
	VGA_GFX_CONTROLLER GC_BIT_MASK, 0xff

	VGA_COLOR_CRTC CRTC_VERT_RETRACE_END, 0x0	; Unlock protected regs
	VGA_COLOR_CRTC CRTC_OVERFLOW, 0x10
	VGA_COLOR_CRTC CRTC_PRESET_ROW_SCAN, 0x0
	VGA_COLOR_CRTC CRTC_MAX_SCAN_LINE, 0x40
	VGA_COLOR_CRTC CRTC_START_ADDR_HIGH, 0x0
	VGA_COLOR_CRTC CRTC_START_ADDR_LOW, 0x0
	VGA_COLOR_CRTC CRTC_VERT_DISP_END, 0xef
	VGA_COLOR_CRTC CRTC_OFFSET, 0x14
	VGA_COLOR_CRTC CRTC_UNDERLINE_LOC, 0x0
	VGA_COLOR_CRTC CRTC_MODE_CONTROL, 0xe3
	VGA_COLOR_CRTC CRTC_LINE_COMPARE, 0xff

	; Read VGA_INPUT_STATUS - reuses BC=0FFh from previous write
	ldw wa, 0x3DA
	calr Read_VGA_Register

	; EGA default palette (16 entries)
	VGA_ATTRIBUTE 0x0, 0x0
	VGA_ATTRIBUTE 0x1, 0x1
	VGA_ATTRIBUTE 0x2, 0x2
	VGA_ATTRIBUTE 0x3, 0x3
	VGA_ATTRIBUTE 0x4, 0x4
	VGA_ATTRIBUTE 0x5, 0x5
	VGA_ATTRIBUTE 0x6, 0x14
	VGA_ATTRIBUTE 0x7, 0x7
	VGA_ATTRIBUTE 0x8, 0x38
	VGA_ATTRIBUTE 0x9, 0x39
	VGA_ATTRIBUTE 0xa, 0x3a
	VGA_ATTRIBUTE 0xb, 0x3b
	VGA_ATTRIBUTE 0xc, 0x3c
	VGA_ATTRIBUTE 0xd, 0x3d
	VGA_ATTRIBUTE 0xe, 0x3e
	VGA_ATTRIBUTE 0xf, 0x3f
	VGA_ATTRIBUTE ATTR_MODE_CONTROL, 0x1
	VGA_ATTRIBUTE ATTR_OVERSCAN_COLOR, 0x0
	VGA_ATTRIBUTE ATTR_COLOR_PLANE_ENABLE, 0xf
	VGA_ATTRIBUTE ATTR_HORIZ_PIXEL_PAN, 0x0
	VGA_ATTRIBUTE 0x34, 0x0	; ATTR_COLOR_SELECT + Palette Address Source

	VGA_SEQUENCER 0x6, 0x1

	VGA_COLOR_CRTC CRTC_HORIZ_TOTAL, 0x65
	VGA_COLOR_CRTC CRTC_HORIZ_DISP_END, 0x27
	VGA_COLOR_CRTC CRTC_START_HORIZ_RETRACE, 0x28
	VGA_COLOR_CRTC CRTC_END_HORIZ_RETRACE, 0x29
	VGA_COLOR_CRTC CRTC_VERT_TOTAL, 0xf3
	VGA_COLOR_CRTC CRTC_OVERFLOW, 0x0
	VGA_COLOR_CRTC CRTC_MAX_SCAN_LINE, 0x0
	VGA_COLOR_CRTC CRTC_VERT_RETRACE_START, 0xf2
	VGA_COLOR_CRTC CRTC_VERT_RETRACE_END, 0x3
	VGA_COLOR_CRTC CRTC_START_VERT_BLANK, 0xef
	VGA_COLOR_CRTC CRTC_END_VERT_BLANK, 0xf3

	VGA_SEQUENCER 0x8, 0x1
	VGA_SEQUENCER 0xd, 0x3
	VGA_SEQUENCER 0xf, 0x0

	VGA_COLOR_CRTC 0x19, 0x0	; MN89304-specific
	VGA_COLOR_CRTC 0x1a, 0x10	; MN89304-specific

	VGA_SEQUENCER 0x7, 0x20	; Horiz char counter reset
	VGA_SEQUENCER 0x6, 0x0

	VGA_COLOR_CRTC CRTC_VERT_RETRACE_END, 0x80	; Lock protected regs 0-7

	VGA_WRITE 0x3c6, 0xff	; DAC mask

	; === DAC Palette Setup ===
	VGA_WRITE 0x3c8, 0	; Start at palette index 0

	; Color 0: Black (0, 0, 0)
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register

	; Color 1: White (F, F, F)
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register

	; Color 2: Red (F, 0, 0)
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register

	; Color 3: Green (0, F, 0)
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register

	; Color 4: Blue (0, 0, F)
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register

	; Color 5: Cyan (0, F, F)
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register

	; Color 6: Yellow (F, F, 0)
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register

	; Color 7: Magenta (F, 0, F)
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register
	ldw wa, 0x3C9
	ldw bc, 0xF
	calr Write_VGA_Register

	; Color 8: Dark Blue (0, 0, 4)
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register
	ldw wa, 0x3C9
	lds bc, 0
	calr Write_VGA_Register
	ldw wa, 0x3C9
	lds bc, 4
	calr Write_VGA_Register

	; Call extended sequencer init
	calr VGA_Extended_Init

	; Set up parameters for video buffer initialization
	; These are loaded here; caller provides the actual CALL to fill/copy routines
	ld xwa, 0x43C00
	ldw bc, 0x808	; Fill pattern
	ldw de, 0x9600	; Size in words (38400 = 0x9600)

	; === End of shared VGA init code ===
	; Each ROM must now:
	;   1. CALL its memory fill routine (fills XWA with DE words of BC pattern)
	;   2. LDA XWA, VIDEO_RAM_BASE
	;   3. LD XBC, OFFSCREEN_BUFFER_1
	;   4. LD DE, 320 * 240 / 2
	;   5. CALL its memory copy routine
	;   6. RET_VGA_SEQUENCER 01h, 001h  (turn screen on)
; --- end include: ../shared/vga_init.asm ---

	; === ROM-specific ending: initialize video buffers ===
	; (Boot code runs from high RAM, so these are absolute calls)
	call 0xFFFB18
	ldada_24 xwa, 1703936
	ld xbc, 0x43C00
	ldw de, 0x9600
	call 0xFFFB0F

	; Turn screen on (RET_VGA_SEQUENCER 01h, 001h with JRL optimization)
	VGA_WRITE VGA_SEQ_ADDR, 0x1
	ldw wa, 0x3C5
	lds bc, 1
	jrl Write_VGA_Register

; Small utility routine at 0x9FD7E2 (table_data specific, not in maincpu)
; Purpose unknown - possibly initialization/cleanup
VGA_FinalizeInitialization:
	ldmi8 (xwa), 0x0
	lds hl, 0
	ret

; =============================================================================
; FDC HELPER ROUTINES (0x9FD7E8-0x9FD8A4)
; Low-level FDC register access at 0x110000
; =============================================================================

; -----------------------------------------------------------------------------
; FDC_ReadStatus - Read FDC main status register
; Address: 0x9FD7E8
; Returns: L = status byte from 0x110008
; -----------------------------------------------------------------------------
FDC_ReadStatus:
	ldda8_24 l, 1114120	; LD L, (0x110008)
	ret	; 0e

; -----------------------------------------------------------------------------
; FDC_ReadData - Read FDC data register
; Address: 0x9FD7EE
; Returns: L = data byte from 0x11000A
; -----------------------------------------------------------------------------
FDC_ReadData:
	ldda8_24 l, 1114122	; LD L, (0x11000A)
	ret	; 0e

; -----------------------------------------------------------------------------
; FDC_WriteStatus - Write to FDC status register
; Address: 0x9FD7F4
; Input: A = value to write
; -----------------------------------------------------------------------------
FDC_WriteStatus:
	stda8_24 1114120, a	; LD (0x110008), A
	ret	; 0e

; -----------------------------------------------------------------------------
; FDC_SaveCommand - Save command to history buffer
; Address: 0x9FD7FA
; Saves current command at 0x0D50 to 0x0D4E, stores new command
; -----------------------------------------------------------------------------
FDC_SaveCommand:
	ldmm8 3406, 3408	; LD (0x0D4E), (0x0D50)
	stda8 3408, a	; LD (0x0D50), A
	ret	; 0e

; -----------------------------------------------------------------------------
; FDC_WriteData - Write to FDC data register
; Address: 0x9FD805
; Input: A = value to write
; -----------------------------------------------------------------------------
FDC_WriteData:
	stda8_24 1114122, a	; LD (0x11000A), A
	ret	; 0e

; -----------------------------------------------------------------------------
; FDC_WaitReady - Wait for FDC ready (RQM bit)
; Address: 0x9FD80B
; Polls status register until ready or timeout
; Returns via FDC_Error (0x9FE231) on timeout
; -----------------------------------------------------------------------------
FDC_WaitReady:
	push xiz	; 3e
	ldda16 xiz, 3072	; LD IZ, (0x0C00) - get timer
	erpw4 0xFA, 0x03, 0x80, 0x00	; LD QIZ, 0x0080 - flag = pending

FDC_WaitReady__fwr_check:
	erpw4 0xFA, 0xCF, 0x80, 0x00	; CP QIZ, 0x0080
	jr nz, FDC_WaitReady__fwr_check_result	; 6e 29
FDC_WaitReady__fwr_loop:
	.byte 0x1e, 0xc9, 0xff	; CALR FDC_ReadStatus
	and l, 0x1F	; AND L, 0x1F - mask status bits
	ld a, l	; LD A, L
	extpfx2 0xD8, 0x12	; EXTZ WA
	cps wa, 0	; CP WA, 0 - check if ready
	jr nz, FDC_WaitReady__fwr_not_ready	; 6e 03
	ldi0_werp 0xFA	; LD QIZ, 0 - flag = success

FDC_WaitReady__fwr_not_ready:
	ldda16 xwa, 3072	; LD WA, (0x0C00)
	extpfx2 0xDE, 0xA0	; SUB WA, IZ
	cp wa, 0x1F4	; CP WA, 0x01F4 (500) - timeout
	jr ule, FDC_WaitReady__fwr_continue	; 63 05
	erpw4 0xFA, 0x03, 0xFF, 0xFF	; LD QIZ, 0xFFFF - flag = timeout

FDC_WaitReady__fwr_continue:
	erpw4 0xFA, 0xCF, 0x80, 0x00	; CP QIZ, 0x0080
	jr z, FDC_WaitReady__fwr_loop	; 66 d7

FDC_WaitReady__fwr_check_result:
	cpi0_werp 0xFA	; CP QIZ, 0
	jr z, FDC_WaitReady__fwr_done	; 66 05
	lds wa, 1	; LD WA, 1 - error code
	.byte 0x1e, 0xe2, 0x09	; CALR 0x9FE231 (FDC_Error)

FDC_WaitReady__fwr_done:
	pop xiz	; 5e
	ret	; 0e

; -----------------------------------------------------------------------------
; FDC_WaitComplete - Wait for FDC command complete
; Address: 0x9FD851
; Polls for DIO and RQM bits set (0x90)
; -----------------------------------------------------------------------------
FDC_WaitComplete:
	push xiz	; 3e
	ldda16 xiz, 3072	; LD IZ, (0x0C00)
	erpw4 0xFA, 0x03, 0x80, 0x00	; LD QIZ, 0x0080

FDC_WaitComplete__fwc_check:
	erpw4 0xFA, 0xCF, 0x80, 0x00	; CP QIZ, 0x0080
	jr nz, FDC_WaitComplete__fwc_check_result	; 6e 26
FDC_WaitComplete__fwc_loop:
	.byte 0x1e, 0x83, 0xff	; CALR FDC_ReadStatus
	and l, 0x90	; AND L, 0x90 - mask DIO+RQM
	cp l, 0x90	; CP L, 0x90 - both set?
	jr nz, FDC_WaitComplete__fwc_not_done	; 6e 03
	ldi0_werp 0xFA	; LD QIZ, 0 - success

FDC_WaitComplete__fwc_not_done:
	ldda16 xwa, 3072	; LD WA, (0x0C00)
	extpfx2 0xDE, 0xA0	; SUB WA, IZ
	cp wa, 0x1F4	; CP WA, 0x01F4 - timeout
	jr ule, FDC_WaitComplete__fwc_continue	; 63 05
	erpw4 0xFA, 0x03, 0xFF, 0xFF	; LD QIZ, 0xFFFF

FDC_WaitComplete__fwc_continue:
	erpw4 0xFA, 0xCF, 0x80, 0x00	; CP QIZ, 0x0080
	jr z, FDC_WaitComplete__fwc_loop	; 66 da

FDC_WaitComplete__fwc_check_result:
	cpi0_werp 0xFA	; CP QIZ, 0
	jr z, FDC_WaitComplete__fwc_done	; 66 05
	lds wa, 1	; LD WA, 1
	.byte 0x1e, 0x9f, 0x09	; CALR 0x9FE231

FDC_WaitComplete__fwc_done:
	pop xiz	; 5e
	ret	; 0e

; -----------------------------------------------------------------------------
; FDC_Seek - Send seek command
; Address: 0x9FD894
; Sends seek command 0x36 to FDC, delays for motor spinup
; -----------------------------------------------------------------------------
FDC_Seek:
	ldw wa, 0x36	; LD WA, 0x0036 - SEEK command
	.byte 0x1e, 0x5a, 0xff	; CALR FDC_WriteStatus
	lds wa, 2	; LD WA, 2 - delay parameter
	.byte 0x1e, 0xf7, 0x09	; CALR 0x9FE296 (delay routine)
	stdi8 3378, 255	; LD (0x0D32), 0xFF - set flag
	ret	; 0e

; =============================================================================
; Flash Update Type Handlers
; Address: 0x9FD8A5-0x9FEA9C (4600 bytes)
;
; These handlers process different firmware update disk types:
;   Type 1: Table Data disk 1 of 2
;   Type 2: Table Data disk 2 of 2
;   Type 3: Custom Data flash update
;   Type 4: HDAE5000 expansion ROM
;   Type 5: Compressed program ROM
;   Type 6: Compressed table data ROM
;   Type 7: Combined update disk 1
;   Type 8: Combined update disk 2
;
; Each handler:
;   - Validates disk format and checksums
;   - Erases appropriate flash sectors
;   - Programs new firmware data
;   - Updates progress display
; =============================================================================
	.incbin "../includes/bootcode_flash_handlers.bin"

; =============================================================================
; BootTimer_InterruptHandler - Timer Counter 3 Interrupt Handler
; Address: 0x9FEA9D (boot-time: 0xFFEA9D)
;
; Simple system tick handler:
;   - Saves all registers
;   - Calls Boot_TimerTick (0x9FDD17) to increment system timer
;   - Calls Boot_UpdateDisplay (0x9FDD26) to refresh VGA display
;   - Restores registers and returns from interrupt
; =============================================================================
BootTimer_InterruptHandler:
	push xiz	; 3e - save all registers
	push xiy	; 3d
	push xix	; 3c
	push xhl	; 3b
	push xde	; 3a
	push xbc	; 39
	push xwa	; 38
	.byte 0x1e, 0x70, 0xf2	; CALR Boot_TimerTick (0x9FDD17)
	.byte 0x1e, 0x7c, 0xf2	; CALR Boot_UpdateDisplay (0x9FDD26)
	pop xwa	; 58 - restore all registers
	pop xbc	; 59
	pop xde	; 5a
	pop xhl	; 5b
	pop xix	; 5c
	pop xiy	; 5d
	pop xiz	; 5e
	reti	; 07

; =============================================================================
; Handler_INT4 - FDC (Floppy Disk Controller) Interrupt Handler
; Address: 0x9FEAB2 (boot-time: 0xFFEAB2)
;
; Handles FDC interrupt during firmware update:
;   - Timeout counter (100 iterations max)
;   - Polls FDC status for RQM (bit 7) and DIO (bit 6)
;   - Reads result bytes from FDC data register
;   - Stores results at 0x0C8E buffer
;   - Calls FDC_ProcessResults (0x9FDF17) when complete
; =============================================================================
Handler_INT4:
	push xiz	; 3e
	push xiy	; 3d
	push xix	; 3c
	push xhl	; 3b
	push xde	; 3a
	push xbc	; 39
	push xwa	; 38
	lds iz, 0	; LD IZ, 0 - timeout counter

Handler_INT4__int4_check_timeout:
	ld wa, iz	; LD WA, IZ - get current count
	inc 1, iz	; INC 1, IZ
	cp wa, 0x64	; CP WA, 0x0064 (100)
	jr gt, Handler_INT4__int4_done	; 6a 59 - timeout exceeded

	.byte 0x1e, 0x20, 0xed	; CALR FDC_ReadStatus (0x9FD7E8)
	bit 7, l	; BIT 7, L - check RQM (request for master)
	jr z, Handler_INT4__int4_check_timeout	; 66 ee - not ready, keep polling

Handler_INT4__int4_wait_rqm:
	.byte 0x1e, 0x18, 0xed	; CALR FDC_ReadStatus
	bit 7, l	; BIT 7, L
	jr z, Handler_INT4__int4_wait_rqm	; 66 f8

	.byte 0x1e, 0x10, 0xed	; CALR FDC_ReadStatus
	bit 6, l	; BIT 6, L - check DIO (data direction)
	jr nz, Handler_INT4__int4_setup_buffer	; 6e 18 - FDC has data for us

	; FDC needs data from us - send sense interrupt command
	ldb l, 0x0	; LD L, 0x00
	cp l, 0x80	; CP L, 0x80
	jr z, Handler_INT4__int4_send_cmd	; 66 0b

Handler_INT4__int4_poll_ready:
	.byte 0x1e, 0x01, 0xed	; CALR FDC_ReadStatus
	and l, 0xF0	; AND L, 0xF0 - mask status bits
	cp l, 0x80	; CP L, 0x80 - RQM set, DIO clear?
	jr nz, Handler_INT4__int4_poll_ready	; 6e f5

Handler_INT4__int4_send_cmd:
	ldw wa, 0x8	; LD WA, 0x0008 - sense interrupt command
	.byte 0x1e, 0x10, 0xed	; CALR FDC_WriteData (0x9FD805)

Handler_INT4__int4_setup_buffer:
	ldada xiz, 3214	; LDA XIZ, 0x0C8E - result buffer
	inc 1, xiz	; INC 1, XIZ

Handler_INT4__int4_read_loop:
	.byte 0x1e, 0xef, 0xf2	; CALR Boot_ClearWatchdog (0x9FDDED)
	.byte 0x1e, 0xed, 0xec	; CALR FDC_ReadData (0x9FD7EE)
	dpi2 0xF8, 0x47	; LD (XIZ+), L - store result byte

Handler_INT4__int4_check_more:
	.byte 0x1e, 0xe1, 0xec	; CALR FDC_ReadStatus
	bit 7, l	; BIT 7, L - RQM set?
	jr z, Handler_INT4__int4_check_more	; 66 f8 - wait for ready

	.byte 0x1e, 0xd9, 0xec	; CALR FDC_ReadStatus
	bit 6, l	; BIT 6, L - DIO set?
	jr nz, Handler_INT4__int4_read_loop	; 6e e7 - more data to read

	.byte 0x1e, 0x00, 0xf4	; CALR FDC_ProcessResults (0x9FDF17)
	cpdi8 3215, 128	; CP (0x0C8F), 0x80 - check status
	jr nz, Handler_INT4__int4_wait_rqm	; 6e af - not done, continue

Handler_INT4__int4_done:
	stdi8 3214, 0	; LD (0x0C8E), 0x0000 - clear buffer
	pop xwa	; 58
	pop xbc	; 59
	pop xde	; 5a
	pop xhl	; 5b
	pop xix	; 5c
	pop xiy	; 5d
	pop xiz	; 5e
	reti	; 07

; =============================================================================
; Boot ROM Utility Routines
; Address: 0x9FEB2B-0x9FF228 (1790 bytes)
;
; Contains various utility routines:
;   - Motor control timing
;   - VGA display routines for update UI
;   - Disk format detection helpers
;   - Progress bar updates
